    let version: String
    let input: ReplicateInput
    // Set streaming to true for real-time chat tokens
    // We will use polling (false) for simplicity in this first example
    var stream: Bool = false
}

struct PredictionResponse: Codable {
    let id: String
    let status: String
    let urls: [String: String]?
    let output: [String]? // For non-streaming output
}


