    private let session = URLSession.shared

    func getVicunaResponse(for prompt: String, completion: @escaping (Result<String, Error>) -> Void) {
        // Vicuna uses a specific prompt format
        let formattedPrompt = "USER: \(prompt)\nASSISTANT:"

        createPrediction(for: formattedPrompt) { [weak self] result in
            switch result {
            case .success(let initialResponse):
                // Poll for the result
                self?.pollForResult(predictionURL: initialResponse.urls!["get"]!) { pollResult in
                    completion(pollResult)
                }
            case .failure(let error):
                completion(.failure(error))
            }
        }
    }

    private func createPrediction(for prompt: String, completion: @escaping (Result<PredictionResponse, Error>) -> Void) {
        let url = URL(string: "https://api.replicate.com/v1/predictions")!
        var request = URLRequest(url: url)
        request.httpMethod = "POST"
        request.addValue("application/json", forHTTPHeaderField: "Content-Type")
        request.addValue("Token \(apiKey)", forHTTPHeaderField: "Authorization")

        let input = ReplicateInput(prompt: prompt)
        let payload = PredictionRequest(version: modelVersion, input: input)

        do {
            request.httpBody = try JSONEncoder().encode(payload)
        } catch {
            completion(.failure(error))
            return
        }

        session.dataTask(with: request) { data, _, error in
            if let error = error {
                completion(.failure(error))
                return
            }
            guard let data = data else { return }

            do {
                let response = try JSONDecoder().decode(PredictionResponse.self, from: data)
                completion(.success(response))
            } catch {
                completion(.failure(error))
            }
        }.resume()
    }

    private func pollForResult(predictionURL: String, completion: @escaping (Result<String, Error>) -> Void) {
        let url = URL(string: predictionURL)!
        var request = URLRequest(url: url)
        request.addValue("Token \(apiKey)", forHTTPHeaderField: "Authorization")

        session.dataTask(with: request) { data, _, error in
            if let error = error {
                completion(.failure(error))
                return
            }
            guard let data = data else { return }

            do {
                let response = try JSONDecoder().decode(PredictionResponse.self, from: data)

                switch response.status {
                case "succeeded":
                    // The output is an array of strings, join them.
                    let combinedOutput = response.output?.joined() ?? ""
                    completion(.success(combinedOutput))
                case "starting", "processing":
                    // Still processing, poll again after a short delay
                    DispatchQueue.main.asyncAfter(deadline: .now() + 1.0) {
                        self.pollForResult(predictionURL: predictionURL, completion: completion)
                    }
                default:
                    // Failed or canceled
                    completion(.failure(NSError(domain: "", code: 0, userInfo: [NSLocalizedDescriptionKey: "Prediction failed with status: \(response.status)"])))
                }
            } catch {
                completion(.failure(error))
            }
        }.resume()
    }
}
```

